// Value types can't normally be null
// int x = null; // ERROR!

// Use ? to make them nullable
int? age = null;
double? price = 19.99;
bool? isActive = null;

// Check HasValue or use GetValueOrDefault()
if (age.HasValue)
{
    Console.WriteLine(age.Value);
}
else
{
    Console.WriteLine("Age is unknown");
}

// Null-coalescing operator
int years = age ?? 0; // If null, use 0
int actual = age.GetValueOrDefault();
int def = age.GetValueOrDefault(18); // Default value

// Enable nullable reference types
#nullable enable

// string can be null by default
string? middleName = null; // Explicitly nullable
string firstName = "Alice"; // Non-nullable

// Compiler warns about potential nulls
if (firstName != null)
{
    Console.WriteLine(firstName.Length); // OK
}

// Null-forgiving operator
string name = GetName(); // Might return null
Console.WriteLine(name!.Length); // Tell compiler it's not null
